const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const count=v=>Number.isFinite(v)?Math.max(0,Math.round(v)):0;
export function matchReport(state){
 const h=state.stats?.home||{},a=state.stats?.away||{},dh=state.discipline?.home||{},da=state.discipline?.away||{};
 const rows=[['射门',h.shots,a.shots],['射正',h.onTarget,a.onTarget],['扑救',h.saves,a.saves],['传球',h.passes,a.passes],['抢断',h.tackles,a.tackles],['黄牌',dh.yellows,da.yellows],['红牌',dh.reds,da.reds]].map(([label,home,away])=>{home=count(home);away=count(away);return{label,home,away,homeWidth:home+away?home/(home+away)*100:0,awayWidth:home+away?away/(home+away)*100:0};});
 const shootout=state.competition?.shootout;return{home:'拜仁',away:state.fixture?.short||'客队',score:[count(state.score?.home),count(state.score?.away)],penalties:shootout?[shootout.home.filter(Boolean).length,shootout.away.filter(Boolean).length]:null,rows};
}
export function buildMatchReport(root){let previous='';return{update(state,visible){if(root.hidden!==!visible)root.hidden=!visible;if(!visible)return;const model=matchReport(state),key=JSON.stringify(model);if(key===previous)return;previous=key;root.innerHTML=`<div class="report-score"><span><small>主队</small><b>${escape(model.home)}</b></span><strong>${model.score[0]}<em>:</em>${model.score[1]}</strong><span><small>客队</small><b>${escape(model.away)}</b></span></div>${model.penalties?`<p class="report-penalties">点球 ${model.penalties[0]} : ${model.penalties[1]}</p>`:''}<div class="report-rows">${model.rows.map(r=>`<div class="report-row" aria-label="${r.label}，拜仁 ${r.home}，${escape(model.away)} ${r.away}"><span>${r.home}</span><b>${r.label}</b><span>${r.away}</span><div class="report-track"><i style="width:${r.homeWidth}%"></i><i style="width:${r.awayWidth}%"></i></div></div>`).join('')}</div>`;}};}
